    </div>

    <div class="section-title">1. Joining Date</div>
    <div class="paragraph">
        You will be designated as a <strong>{{ $candidate->position }}</strong>, and your employment will commence from <strong>{{ \Carbon\Carbon::parse($candidate->joining_date)->format('d/m/Y') }}</strong>.
    </div>
